SELECT ?band ?bandLabel ?location ?locationLabel WHERE {
  ?band wdt:P527 ?member .
  ?member rdfs:label "King ov Hell"@en .
  ?band wdt:P159 ?location .
  ?location wdt:P131* wd:Q1718 . # Q1718 is Hordaland county (verify actual Wikidata code)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

UNION

SELECT ?band ?bandLabel ?location ?locationLabel WHERE {
  ?band wdt:P527 ?member .
  ?member rdfs:label ?memberName .
  FILTER(CONTAINS(LCASE(?memberName), "king ov hell")) .
  ?band wdt:P159 ?location .
  ?location rdfs:label ?locationLabel FILTER(CONTAINS(LCASE(?locationLabel), "hordaland")) .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

LIMIT 10

