SELECT ?director ?directorProfession ?kordaProfession WHERE {
  ?film wdt:P31 wd:Q11424;  # instance of film
        rdfs:label "Little Children"@en;
        wdt:P577 ?date; 
        wdt:P57 ?director.
  FILTER(YEAR(?date) = 2006)
  ?director wdt:P106 ?directorProfessionEntity.
  ?directorProfessionEntity rdfs:label ?directorProfession FILTER(LANG(?directorProfession) = "en").

  wd:Q73975 wdt:P106 ?kordaProfessionEntity.
  ?kordaProfessionEntity rdfs:label ?kordaProfession FILTER(LANG(?kordaProfession) = "en").

  FILTER(?directorProfessionEntity IN (wd:Q2526255, wd:Q286749)) # film director, media person profession

  FILTER(?kordaProfessionEntity IN (wd:Q2526255, wd:Q286749))
}

