SELECT ?band ?hostedShow WHERE {
  ?band wdt:P175 wd:Q1545440.  # Defari's Wikidata entity assumed Q1545440, to verify actual ID
  ?person wdt:P_memberOf ?band.
  ?person wdt:P106 wd:Q639669.  # occupation: musician
  ?show wdt:P175 ?person;
        wdt:P31 wd:Q15401676; # instance of television show
        wdt:P859 ?hostedShowName. 
  FILTER(CONTAINS(LCASE(?hostedShowName), "you can't see me"))
} LIMIT 10

SELECT DISTINCT ?song ?originalArtist ?originalArtistGenre WHERE {
  ?song wdt:P175 wd:Q102340;                      # performer Kathy Mattea
        p:P1117 ?chartEntry.                      # chart performance statement
  ?chartEntry ps:P1117 ?chart;
               pq:P1352 wd:Q15801257.             # Billboard Hot Country Singles & Tracks chart
  ?chart pq:P1352 wd:Q15801257;
         pq:P1353 ?peakPosition.
  FILTER(?peakPosition = 1)

  # Find the original recording artist
  ?song wdt:P4380 ?originalArtist.                # original artist property P4380 if available

  # Get the genre of the original artist
  OPTIONAL {
    ?originalArtist wdt:P136 ?genre.
  }

  ?originalArtist wdt:P31 wd:Q5.                   # instance of human
  ?originalArtist wdt:P101 ?occupation.            # occupation
  FILTER(CONTAINS(LCASE(STR(?occupation)), "country"))
}
LIMIT 10

